#!/usr/bin/env node
// The types and JSON Schema of the Codex app-server protocol, generated by the pinned Codex
// (worfy-multi-vendor ticket 17):
//
//   node scripts/codex-protocol.mjs [--root <repo>]           generate
//   node scripts/codex-protocol.mjs --check [--root <repo>]   part of pnpm lint; Codex is not run
//
// Generate runs the Codex of node_modules (`@openai/codex`, the exact version of package.json) twice:
// `codex app-server generate-ts` and `codex app-server generate-json-schema`, without
// `--experimental` (worfy does not lean on experimental methods: spec of worfy-multi-vendor, "Codex:
// binary and compatibility"). The output replaces src/main/vendors/codex/protocol/ts/ and
// protocol/json/, and protocol/VERSION gets the version it was made with. Each output is specific to
// the Codex version: after a change of `@openai/codex` in package.json, run this again and commit the
// result. Nobody writes or edits these files by hand.
//
// Codex runs with CODEX_HOME in a fresh temporary folder, removed afterwards: generating the protocol
// reads no configuration, and the user's ~/.codex is never touched.
//
// --check compares protocol/VERSION with the version of `@openai/codex` in package.json and checks that
// protocol/ts/ and protocol/json/ are there. A mismatch prints `<file>: <what is wrong>` to stderr and
// exits 1; a clean check prints `codex-protocol: ok (<version>)` and exits 0. A package.json that cannot
// be read exits 2.

import { spawnSync } from 'node:child_process'
import { cpSync, existsSync, mkdirSync, mkdtempSync, readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { createRequire } from 'node:module'
import { tmpdir } from 'node:os'
import { dirname, join } from 'node:path'
import process from 'node:process'
import { removeTree } from './remove-tree.mjs'

const PACKAGE = '@openai/codex'
const PROTOCOL = join('src', 'main', 'vendors', 'codex', 'protocol')
const OUTPUTS = [
  { dir: 'ts', command: 'generate-ts' },
  { dir: 'json', command: 'generate-json-schema' },
]

function fail(code, message) {
  process.stderr.write(`codex-protocol: ${message}\n`)
  return code
}

/** The exact version of `@openai/codex` in the package.json of `root`. */
function pinnedVersion(root) {
  const manifest = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'))
  const version = manifest.dependencies?.[PACKAGE]
  if (typeof version !== 'string' || !/^\d+\.\d+\.\d+$/.test(version)) {
    throw new Error(`package.json: ${PACKAGE} must be in dependencies with an exact version, found ${JSON.stringify(version)}`)
  }
  return version
}

function check(root) {
  let version
  try {
    version = pinnedVersion(root)
  } catch (error) {
    return fail(2, error.message)
  }
  const protocol = join(root, PROTOCOL)
  const problems = []
  const versionFile = join(protocol, 'VERSION')
  if (!existsSync(versionFile)) problems.push(`${PROTOCOL}/VERSION: missing; run node scripts/codex-protocol.mjs`)
  else {
    const generated = readFileSync(versionFile, 'utf8').trim()
    if (generated !== version) {
      problems.push(`${PROTOCOL}/VERSION: generated by Codex ${generated}, package.json pins ${version}; run node scripts/codex-protocol.mjs`)
    }
  }
  for (const { dir } of OUTPUTS) {
    const path = join(protocol, dir)
    if (!existsSync(path) || readdirSync(path).length === 0) problems.push(`${PROTOCOL}/${dir}: missing or empty; run node scripts/codex-protocol.mjs`)
  }
  if (problems.length > 0) {
    for (const problem of problems) process.stderr.write(`${problem}\n`)
    return 1
  }
  process.stdout.write(`codex-protocol: ok (${version})\n`)
  return 0
}

function generate(root) {
  const version = pinnedVersion(root)
  // The launcher of the package picks the binary of this platform's package, as `codex` on PATH would.
  const launcher = createRequire(join(root, 'package.json')).resolve(`${PACKAGE}/bin/codex.js`)
  const installed = JSON.parse(readFileSync(join(dirname(launcher), '..', 'package.json'), 'utf8')).version
  if (installed !== version) return fail(1, `node_modules has ${PACKAGE} ${installed}, package.json pins ${version}; run pnpm install`)
  const work = mkdtempSync(join(tmpdir(), 'worfy-codex-protocol-'))
  try {
    const home = join(work, 'codex-home')
    mkdirSync(home)
    const env = { ...process.env, CODEX_HOME: home }
    for (const { dir, command } of OUTPUTS) {
      const out = join(work, dir)
      const result = spawnSync(process.execPath, [launcher, 'app-server', command, '--out', out], { env, stdio: 'inherit' })
      if (result.error) return fail(1, `codex app-server ${command}: ${result.error.message}`)
      if (result.status !== 0) return fail(1, `codex app-server ${command} exited with ${result.status ?? result.signal}`)
    }
    const protocol = join(root, PROTOCOL)
    for (const { dir } of OUTPUTS) {
      // A copy, not a rename: the temporary folder may sit on another volume than the repository.
      removeTree(join(protocol, dir))
      cpSync(join(work, dir), join(protocol, dir), { recursive: true })
    }
    writeFileSync(join(protocol, 'VERSION'), `${version}\n`)
    process.stdout.write(`codex-protocol: generated ${PROTOCOL}/ts and ${PROTOCOL}/json with Codex ${version}\n`)
    return 0
  } finally {
    removeTree(work)
  }
}

function main(argv) {
  let root = join(import.meta.dirname, '..')
  let checkOnly = false
  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index]
    if (arg === '--check') checkOnly = true
    else if (arg === '--root' && argv[index + 1]) root = argv[(index += 1)]
    else return fail(2, `unknown argument ${arg}`)
  }
  if (checkOnly) return check(root)
  try {
    return generate(root)
  } catch (error) {
    return fail(1, error.message)
  }
}

process.exitCode = main(process.argv.slice(2))
